await ev("'`document.querySelector('"'[data-counter=\"bedrooms\"][data-change=\"1\"]').click();document.querySelector('input[value=\"Cats\"]').click();document.querySelector('#notes').value='Please focus on the kitchen.';document.querySelector('#next-button').click()"'`);assert.equal(await ev('"'state.bedrooms'),3);assert.equal(await ev('state.pets'),'Cats');assert.equal(await ev('state.step'),2);
await ev('document.querySelector(\"#next-button\").click()');assert.equal(await ev('document.querySelector(\"#date-error\").hidden'),false);
await ev("'`if(!document.querySelector('"'.day:not(:disabled)'))document.querySelector('#next-month').click();document.querySelector('.day:not(:disabled)').click();document.querySelector('.time-slot').click();document.querySelector('#next-button').click()"'`);assert.equal(await ev('"'state.step'),3);assert.match(await ev('content.innerText'),/\\"'$155/);assert.match(await ev('"'content.innerText'),/Alex Morgan/);
await ev("'`document.querySelector('"'[data-edit=\"0\"]').click()"'`);assert.equal(await ev('"'document.querySelector(\"#apartment\").value'),'3B');await ev("'`document.querySelector('"'#next-button').click();document.querySelector('#next-button').click();document.querySelector('#next-button').click()"'`);assert.equal(await ev('"'state.step'),3);assert.match(await ev('content.innerText'),/Please focus on the kitchen/);
await ev("'`document.querySelector('"'#next-button').click()"'`);assert.equal(await ev('"'"'!!document.querySelector("#success-title")'"'),true);await ev("'`document.querySelector('"'#new-booking').click()"'`);assert.equal(await ev('"'document.querySelector(\"#firstName\").value'),'');
console.log('PASS: required fields, saved details, counters, pets, date/time validation, review edits, price, confirmation, reset');
await c('Page.captureScreenshot',{format:'png'}).then(r=>fs.writeFileSync('/tmp/neat-flow-desktop.png',Buffer.from(r.data,'base64')));
for(const width of [320,375,390,768]){await c('Emulation.setDeviceMetricsOverride',{width,height:844,deviceScaleFactor:1,mobile:true});assert.equal(await ev('document.documentElement.scrollWidth<=window.innerWidth'),true,"'`Overflow at ${width}`);console.log('"'PASS: no horizontal overflow at',width);if(width===390)await c('Page.captureScreenshot',{format:'png',captureBeyondViewport:true}).then(r=>fs.writeFileSync('/tmp/neat-flow-mobile.png',Buffer.from(r.data,'base64')));}
await ev("'`document.querySelector('"'[data-dialog=\"help\"]').click()"'`);assert.equal(await ev('"'document.querySelector(\"#info-dialog\").open'),true);await ev("'`document.querySelector('"'#close-dialog').click()"'`);assert.equal(await ev('"'document.querySelector(\"#info-dialog\").open'),false);console.log('PASS: help dialog');clearTimeout(timeout);browser.kill();})().catch(e=>{console.error(e);clearTimeout(timeout);browser.kill();process.exit(1)});
EOF
